+import type { Reading } from "./readings";
+
+export type Trend = "rising" | "steady" | "falling";
+
+export function pressureTrend(readings: Reading[], hours = 3): Trend {
+  const recent = readings.slice(-hours - 1);
+
+  if (recent.length < 2) {
+    return "steady";
+  }
+
+  const change = recent[recent.length - 1].pressure - recent[0].pressure;
+
+  if (change > 1) {
+    return "rising";
+  }
+
+  return change < -1 ? "falling" : "steady";
+}
