+import type { Reading } from "../readings";
+
+const SECTORS = 16;
+const COMPASS = ["N", "E", "S", "W"];
+
+export function windRose(readings: Reading[], size = 180): SVGSVGElement {
+  const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
+  svg.setAttribute("viewBox", `0 0 ${size} ${size}`);
+
+  const counts = new Array<number>(SECTORS).fill(0);
+
+  for (const reading of readings) {
+    const sector = Math.round(reading.windDirection / (360 / SECTORS)) % SECTORS;
+    counts[sector] += 1;
+  }
+
+  const peak = Math.max(...counts, 1);
+  const center = size / 2;
+
+  counts.forEach((count, sector) => {
+    const angle = ((sector * 360) / SECTORS - 90) * (Math.PI / 180);
+    const length = (count / peak) * (center - 24);
+
+    const petal = document.createElementNS("http://www.w3.org/2000/svg", "line");
+    petal.setAttribute("x1", String(center));
+    petal.setAttribute("y1", String(center));
+    petal.setAttribute("x2", String(center + Math.cos(angle) * length));
+    petal.setAttribute("y2", String(center + Math.sin(angle) * length));
+    petal.setAttribute("class", "wind-rose-petal");
+    svg.append(petal);
+  });
+
+  COMPASS.forEach((label, index) => {
+    const angle = (index * 90 - 90) * (Math.PI / 180);
+    const text = document.createElementNS("http://www.w3.org/2000/svg", "text");
+    text.setAttribute("x", String(center + Math.cos(angle) * (center - 8)));
+    text.setAttribute("y", String(center + Math.sin(angle) * (center - 8)));
+    text.setAttribute("class", "wind-rose-label");
+    text.textContent = label;
+    svg.append(text);
+  });
+
+  return svg;
+}

