+export interface SparklineOptions {
+  width: number;
+  height: number;
+  stroke: string;
+}
+
+const DEFAULT_OPTIONS: SparklineOptions = { width: 160, height: 36, stroke: "#2a6b9e" };
+
+export function sparkline(values: number[], options: Partial<SparklineOptions> = {}): SVGSVGElement {
+  const { width, height, stroke } = { ...DEFAULT_OPTIONS, ...options };
+  const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
+  svg.setAttribute("viewBox", `0 0 ${width} ${height}`);
+
+  if (values.length < 2) {
+    return svg;
+  }
+
+  const min = Math.min(...values);
+  const max = Math.max(...values);
+  const range = max - min || 1;
+
+  const points = values.map((value, index) => {
+    const x = (index / (values.length - 1)) * width;
+    const y = height - ((value - min) / range) * height;
+    return `${x.toFixed(1)},${y.toFixed(1)}`;
+  });
+
+  const line = document.createElementNS("http://www.w3.org/2000/svg", "polyline");
+  line.setAttribute("points", points.join(" "));
+  line.setAttribute("fill", "none");
+  line.setAttribute("stroke", stroke);
+  line.setAttribute("stroke-width", "2");
+  svg.append(line);
+
+  return svg;
+}

