+function renderStation(station: Station): HTMLElement {
+  const card = document.createElement("article");
+  card.className = "station-card";
+  card.innerHTML = `
+    <h2>${station.name}</h2>
+    <p class="elevation">${station.elevation} m</p>
+  `;
