+export interface Reading {
+  stationId: string;
+  takenAt: Date;
+  temperature: number;
+  humidity: number;
+  pressure: number;
+  windSpeed: number;
+  windDirection: number;
+}
+
+export function parseReading(line: string): Reading {
+  const [stationId, takenAt, temperature, humidity, pressure, windSpeed, windDirection] = line.split(",");
+
+  return {
+    stationId,
+    takenAt: new Date(takenAt),
+    temperature: Number(temperature),
